"""Seating charts for a class."""

from typing import List
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    return (student.last_name, student.first_name)


def _lines(ordered: List[Student], seats: int) -> List[str]:
    lines = []
    for start in range(0, len(ordered), seats):
        group = ordered[start:start + seats]
        names = [item.display_name for item in group]
        label = " | ".join(names)
        lines.append(f"Row {len(lines) + 1}: {label}")
    return lines


# ---
def seat_rows(
    students: List[Student], seats: int
) -> List[str]:
    if seats < 1 or not students:
        raise ProjectError("need students and a seat count")
    ordered = sorted(students, key=_sort_key)
    return _lines(ordered, seats)

