import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_fills_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbot", "Ona"),
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Abbot, Ona | Dunmere, Piet",
                "Row 2: Halloway, Juno",
            ],
        )

    def test_bad_seat_count_raises(self):
        people = [make("Abbot", "Ona")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
